package com.smartdroneinspection.infrastructure.payment;

import com.smartdroneinspection.contracts.gateway.SepayGateway;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.springframework.util.StringUtils;

/**
 * Sepay VietQR gateway implementation.
 *
 * <p>Sepay has no hosted checkout API: it only notifies merchants of bank transactions. The QR
 * image itself is generated by the public VietQR image service, embedding the merchant account,
 * amount and a transfer description that carries the occurrence's order code so Sepay's webhook can
 * match the incoming transaction.
 */
public class SepayPaymentGateway implements SepayGateway {

  private final SepayProperties properties;

  public SepayPaymentGateway(SepayProperties properties) {
    this.properties = properties;
  }

  @Override
  public SepayPaymentLink createPaymentLink(
      long orderCode,
      long amount,
      String description,
      String accountNumber,
      String bankName,
      String accountHolder) {
    String acc = firstNonBlank(accountNumber, properties.accountNumber());
    String bank = firstNonBlank(bankName, properties.bankName());
    String holder = firstNonBlank(accountHolder, properties.accountHolder());
    if (!StringUtils.hasText(acc) || !StringUtils.hasText(bank)) {
      throw new IllegalStateException(
          "Sepay merchant account number and bank name are required to build a VietQR code.");
    }
    String transferContent = "SDI" + orderCode;
    String qrUrl =
        properties.qrBaseUrl()
            + "/img?acc="
            + url(acc)
            + "&bank="
            + url(bank)
            + "&amount="
            + amount
            + "&des="
            + url(transferContent)
            + "&template=compact"
            + (StringUtils.hasText(holder) ? "&holder=" + url(holder) : "");
    return new SepayPaymentLink(
        orderCode, qrUrl, transferContent, amount, String.valueOf(orderCode), "PENDING");
  }

  @Override
  public SepayPaymentLink createPayoutLink(
      long payoutOrderCode,
      long amount,
      String accountNumber,
      String bankName,
      String accountHolder) {
    String acc = firstNonBlank(accountNumber);
    String bankCode = normalizeVietQrBankCode(firstNonBlank(bankName));
    String holder = firstNonBlank(accountHolder);
    if (!StringUtils.hasText(acc) || !StringUtils.hasText(bankCode)) {
      throw new IllegalStateException(
          "Inspector bank account number and bank name are required to build a VietQR payout code.");
    }
    String transferContent = "SDIPAY" + payoutOrderCode;
    String qrUrl =
        properties.qrBaseUrl()
            + "/img?acc="
            + url(acc)
            + "&bank="
            + url(bankCode)
            + "&amount="
            + amount
            + "&des="
            + url(transferContent)
            + "&template=compact"
            + (StringUtils.hasText(holder) ? "&holder=" + url(holder) : "");
    return new SepayPaymentLink(
        payoutOrderCode,
        qrUrl,
        transferContent,
        amount,
        String.valueOf(payoutOrderCode),
        "PENDING");
  }

  static String normalizeVietQrBankCode(String raw) {
    if (!StringUtils.hasText(raw)) {
      return null;
    }
    String normalized = raw.trim().toLowerCase(java.util.Locale.ROOT).replaceAll("[\\s_-]+", "");
    return switch (normalized) {
      case "vietcombank", "vcb" -> "VCB";
      case "vietinbank", "ctg", "icb" -> "ICB";
      case "bidv" -> "BIDV";
      case "agribank", "vba" -> "VBA";
      case "techcombank", "tcb" -> "TCB";
      case "mbbank", "mb", "militarybank" -> "MB";
      case "acb" -> "ACB";
      case "vpbank", "vpb" -> "VPB";
      case "tpbank", "tpb", "tienphongbank" -> "TPB";
      case "sacombank", "stb" -> "STB";
      case "vib" -> "VIB";
      case "hdbank", "hdb" -> "HDB";
      case "shb" -> "SHB";
      case "ocb" -> "OCB";
      case "msb", "maritimebank" -> "MSB";
      case "eximbank", "eib" -> "EIB";
      case "lpbank", "lpb", "lienvietpostbank" -> "LPB";
      case "seabank", "seab" -> "SEAB";
      case "namabank", "nab" -> "NAB";
      case "abbank", "abb" -> "ABB";
      case "bacabank", "bab" -> "BAB";
      case "vietabank", "vab" -> "VAB";
      case "pgbank", "pgb" -> "PGB";
      case "kienlongbank", "klb" -> "KLB";
      case "baovietbank", "bvb" -> "BVB";
      case "saigonbank", "sgb" -> "SGB";
      case "ncb" -> "NCB";
      case "vietbank" -> "VIETBANK";
      case "pvcombank", "pvcb" -> "PVCB";
      case "bvbank", "vietcapitalbank", "vccb", "timoplus" -> "VCCB";
      case "shinhan", "shinhanbank", "shbvn" -> "SHBVN";
      case "woori", "wooribank", "wvn" -> "WVN";
      case "cimb" -> "CIMB";
      case "uob" -> "UOB";
      case "hsbc" -> "HSBC";
      case "cake" -> "CAKE";
      case "ubank" -> "UBANK";
      case "timo" -> "TIMO";
      case "publicbank", "pbvn" -> "PBVN";
      case "indovina", "ivb" -> "IVB";
      case "vrb" -> "VRB";
      case "oceanbank", "mbv" -> "OCEANBANK";
      case "gpbank", "gpb" -> "GPB";
      default -> raw.trim();
    };
  }

  @Override
  public String expectedAccountNumber() {
    return properties.accountNumber();
  }

  @Override
  public boolean verifyWebhookApiKey(String receivedApiKey) {
    String configured = properties.apiKey();
    if (configured == null || configured.isBlank() || receivedApiKey == null) {
      return false;
    }
    // Constant-time comparison via SHA-256 digest avoids both length leaks and timing attacks.
    try {
      byte[] expected =
          MessageDigest.getInstance("SHA-256").digest(configured.getBytes(StandardCharsets.UTF_8));
      byte[] actual =
          MessageDigest.getInstance("SHA-256")
              .digest(receivedApiKey.getBytes(StandardCharsets.UTF_8));
      int result = 0;
      for (int i = 0; i < expected.length; i++) {
        result |= expected[i] ^ actual[i];
      }
      return result == 0;
    } catch (java.security.NoSuchAlgorithmException ex) {
      throw new IllegalStateException("SHA-256 not available", ex);
    }
  }

  private static String firstNonBlank(String... values) {
    for (String v : values) {
      if (StringUtils.hasText(v)) {
        return v.trim();
      }
    }
    return null;
  }

  private static String url(String value) {
    return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8);
  }
}
